<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { defineStore } from 'pinia'
export type FeedItem={file_id:string;work_id:string;creator_id:string;current_path:string;title:string;creator:string;duration:number|string;reason?:string;library_role?:string;video_label?:string;like_count?:number|null;like_source?:string}
const api=async<T>(path:string,init?:RequestInit):Promise<T>=>{const r=await fetch(path,init);if(!r.ok)throw new Error(await r.text());return r.json()}
const useFeedStore=defineStore('feed',()=>{
 const mode=ref('recommend'),source=ref(localStorage.getItem('source')||'primary'),creatorId=ref(''),creatorName=ref(''),items=ref<FeedItem[]>([]),index=ref(0),page=ref(0),loading=ref(false),hasMore=ref(true),appendLoader=ref<null|(()=>Promise<FeedItem[]>)>(null),liked=ref(new Set<string>()),disliked=ref(new Set<string>()),favorited=ref(new Set<string>()),notice=ref('')
 const current=computed(()=>items.value[index.value])
 async function load(reset=true){if(loading.value)return;if(reset)appendLoader.value=null;loading.value=true;try{const p=reset?0:page.value+1;const q=new URLSearchParams({mode:mode.value,source:source.value,limit:'12',page:String(p)});if(creatorId.value)q.set('creator_id',creatorId.value);const batch=await api<FeedItem[]>(`/api/feed?${q}`);if(reset){items.value=batch;index.value=0;page.value=0}else{items.value.push(...batch);page.value=p}hasMore.value=batch.length===12}finally{loading.value=false}}
 async function loadMore(){if(!hasMore.value||loading.value)return;if(appendLoader.value){loading.value=true;try{const batch=await appendLoader.value();items.value.push(...batch);hasMore.value=batch.length>0}finally{loading.value=false}}else await load(false)}
 async function loadStates(){const [ls,fs]=await Promise.all([api<Array<{file_id:string}>>('/api/collections?type=like').catch(()=>[]),api<Array<{file_id:string}>>('/api/collections?type=favorite').catch(()=>[])]);liked.value=new Set(ls.map(x=>x.file_id));favorited.value=new Set(fs.map(x=>x.file_id))}
 async function collection(kind:'like'|'favorite'){return api<FeedItem[]>(`/api/collections?type=${kind}`)}
 async function event(type:string,x:FeedItem,extra:Record<string,unknown>={}){await api('/api/event',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file_id:x.file_id,work_id:x.work_id,event_type:type,mode:'real',extra})}).catch(()=>{})}
 function flash(message:string){notice.value=message;window.setTimeout(()=>{if(notice.value===message)notice.value=''},1400)}
 async function like(){const x=current.value;if(!x)return;const add=!liked.value.has(x.file_id);add?liked.value.add(x.file_id):liked.value.delete(x.file_id);disliked.value.delete(x.file_id);flash(add?'已喜欢':'已取消喜欢');await event(add?'like':'unlike',x,{creator_id:x.creator_id})}
 async function dislike(){const x=current.value;if(!x)return;disliked.value.add(x.file_id);liked.value.delete(x.file_id);flash('已减少此类推荐');await event('dislike',x,{creator_id:x.creator_id});window.setTimeout(()=>next(1),180)}
 async function toggleFavorite(){const x=current.value;if(!x)return;const add=!favorited.value.has(x.file_id);add?favorited.value.add(x.file_id):favorited.value.delete(x.file_id);flash(add?'已加入收藏':'已取消收藏');await event(add?'favorite':'unfavorite',x,{creator_id:x.creator_id})}
 function setCreator(id:string,name:string){creatorId.value=id;creatorName.value=name;mode.value='creator';void load(true)}
 async function next(delta:number){const n=Math.max(0,Math.min(items.value.length-1,index.value+delta));if(n!==index.value){index.value=n;if(index.value>=items.value.length-3)void loadMore()}}
 return{mode,source,creatorId,creatorName,items,index,current,loading,hasMore,appendLoader,liked,disliked,favorited,notice,load,loadMore,loadStates,collection,event,next,like,dislike,toggleFavorite,setCreator}
})
const store=useFeedStore(),page=ref<'feed'|'like'|'favorite'|'mine'|'following'|'creator'>('feed'),shell=ref<HTMLElement|null>(null),viewport=ref<HTMLElement|null>(null),paused=ref(false),immersive=ref(false),startY=ref(0),moved=ref(false),clickTimer=ref<number|null>(null),detail=ref(''),collectionItems=ref<FeedItem[]>([]),historyStatus=ref<any>(null),autoPlay=ref(localStorage.getItem('autoplay')!=='0'),showMeta=ref(localStorage.getItem('showMeta')!=='0'),soundOn=ref(localStorage.getItem('soundOn')==='1'),videoError=ref(''),followQuery=ref(''),followResults=ref<Array<any>>([]),followingItems=ref<Array<any>>([]),creatorItems=ref<FeedItem[]>([]),activeCreator=ref<any>(null),creatorPage=ref(0),creatorHasMore=ref(false),creatorLoading=ref(false),returnPage=ref<'feed'|'creator'>('feed')
const videoRefs=ref<Record<number,HTMLVideoElement>>({}),preloadCache=new Map<number,HTMLVideoElement>(),slotIndices=computed(()=>[store.index-1,store.index,store.index+1].filter(i=>i>=0&&i<store.items.length))
function media(x:FeedItem){return`/media?path=${encodeURIComponent(x.current_path)}`}
function setVideoRef(i:number,el:Element|null){if(el)videoRefs.value[i]=el as HTMLVideoElement;else delete videoRefs.value[i]}
function warm(i:number){const x=store.items[i];if(!x||preloadCache.has(i))return;const v=document.createElement('video');v.preload='auto';v.muted=true;v.src=media(x);v.load();preloadCache.set(i,v)}
function prepare(i:number){const v=videoRefs.value[i],x=store.items[i];if(!v||!x)return;if(i!==store.index){v.pause();v.autoplay=false}const cached=preloadCache.get(i);if(cached){v.src=cached.src;preloadCache.delete(i)}else if(v.src!==location.origin+media(x))v.src=media(x);v.preload=i===store.index?'auto':'metadata';v.muted=i===store.index?!soundOn.value:true;v.playsInline=true;v.setAttribute('playsinline','');v.setAttribute('webkit-playsinline','');v.setAttribute('x5-playsinline','true');v.onerror=()=>{if(i===store.index)videoError.value='视频加载失败，请点击重试或切换下一个'};v.onloadeddata=()=>{if(i===store.index)videoError.value=''};v.onplay=()=>{if(i===store.index)paused.value=false};v.onpause=()=>{if(i===store.index)paused.value=true};v.onended=()=>{if(i===store.index)void store.next(1)};v.load();if(i===store.index&&autoPlay.value)v.play().catch(()=>{})}
function prepareSlots(){nextTick(()=>{for(const i of slotIndices.value)prepare(i);warm(store.index+1);warm(store.index-1);for(const [i,v] of preloadCache){if(Math.abs(i-store.index)>2){v.pause();v.removeAttribute('src');v.load();preloadCache.delete(i)}}})}
function enableSound(){soundOn.value=true;localStorage.setItem('soundOn','1');const v=videoRefs.value[store.index];if(v){v.muted=false;v.volume=1;if(v.paused)v.play().catch(()=>{})}}
function toggleSound(){if(soundOn.value){soundOn.value=false;localStorage.setItem('soundOn','0');const v=videoRefs.value[store.index];if(v)v.muted=true}else enableSound()}
function singleClick(){enableSound();if(clickTimer.value)clearTimeout(clickTimer.value);clickTimer.value=window.setTimeout(()=>{const v=videoRefs.value[store.index];if(v){videoError.value='';v.paused?v.play().catch(()=>{}):v.pause()}},220)}
function doubleClick(){if(clickTimer.value)clearTimeout(clickTimer.value);void store.like()}
function showSource(){const x=store.current;if(x)detail.value=`来源：${x.library_role||'主库'}\n标签：${x.video_label||'已确认'}\n路径：${x.current_path}`}
function showInfo(){const x=store.current;if(x)detail.value=`作品：${x.title||'未命名'}\n博主：${x.creator||'博主待确认'}\n作品编号：${x.work_id||'暂无'}`}
function touchStart(e:TouchEvent){startY.value=e.touches[0].clientY;moved.value=false}
function touchMove(e:TouchEvent){if(Math.abs(e.touches[0].clientY-startY.value)>12)moved.value=true}
function touchEnd(e:TouchEvent){const d=startY.value-e.changedTouches[0].clientY;if(moved.value&&Math.abs(d)>Math.max(48,window.innerHeight*.12)){void store.next(d>0?1:-1)}else if(!moved.value){enableSound();const v=videoRefs.value[store.index];if(v)v.play().catch(()=>{})}}
function toggleFullscreen(){if(!shell.value)return;if(document.fullscreenElement){void document.exitFullscreen();immersive.value=false}else if(shell.value.requestFullscreen){shell.value.requestFullscreen().then(()=>immersive.value=true).catch(()=>immersive.value=true)}else immersive.value=true;document.body.classList.toggle('locked',immersive.value)}
function fullscreenChanged(){if(!document.fullscreenElement)immersive.value=false;document.body.classList.toggle('locked',immersive.value)}
async function openCollection(kind:'like'|'favorite'){page.value=kind;collectionItems.value=await store.collection(kind)}
function playCollection(i:number){store.items=collectionItems.value;store.index=i;store.hasMore=false;store.appendLoader=null;page.value='feed';prepareSlots()}
async function openMine(){page.value='mine';[historyStatus.value,followingItems.value]=await Promise.all([api('/api/history-status').catch(()=>null),api('/api/following?following=1').catch(()=>[])])}
async function openFollowing(){page.value='following';followQuery.value='';followResults.value=[];followingItems.value=await api('/api/following?following=1').catch(()=>[])}
async function searchCreators(){const q=followQuery.value.trim();followResults.value=q?await api(`/api/following?q=${encodeURIComponent(q)}`).catch(()=>[]):[]}
async function toggleFollow(x:any){const follow=!x.is_following;await api('/api/follow',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({creator_id:x.creator_id,follow})});x.is_following=follow;if(follow){if(!followingItems.value.some(y=>y.creator_id===x.creator_id))followingItems.value.unshift(x)}else followingItems.value=followingItems.value.filter(y=>y.creator_id!==x.creator_id)}
async function openCreator(x:any){activeCreator.value=x;page.value='creator';creatorItems.value=[];creatorPage.value=0;await loadCreatorPage()}
async function loadCreatorPage(){if(creatorLoading.value||!activeCreator.value)return;creatorLoading.value=true;try{const batch=await api<FeedItem[]>(`/api/creator-videos?creator_id=${encodeURIComponent(activeCreator.value.creator_id)}&page=${creatorPage.value}&limit=36`);creatorItems.value.push(...batch);creatorHasMore.value=batch.length===36;creatorPage.value++}finally{creatorLoading.value=false}}
function playCreatorVideo(i:number){store.items=[...creatorItems.value];store.index=i;store.mode='creator';store.creatorId=activeCreator.value?.creator_id||'';store.appendLoader=async()=>{const batch=await api<FeedItem[]>(`/api/creator-videos?creator_id=${encodeURIComponent(activeCreator.value.creator_id)}&page=${creatorPage.value}&limit=36`);creatorPage.value++;creatorHasMore.value=batch.length===36;return batch};store.hasMore=creatorHasMore.value;returnPage.value='creator';page.value='feed';prepareSlots()}
function backFromPlayback(){for(const v of Object.values(videoRefs.value))v.pause();if(returnPage.value==='creator')page.value='creator';else page.value='feed'}
async function importHistory(){await api('/api/history-import',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});historyStatus.value=await api('/api/history-status').catch(()=>null);await store.loadStates();store.flash('历史记录已重新导入')}
function setSource(v:string){store.source=v;localStorage.setItem('source',v);if(page.value==='feed')void store.load()}
watch(()=>store.index,()=>{for(const v of Object.values(videoRefs.value))v.pause()})
watch(()=>[store.index,store.items.length],prepareSlots)
onMounted(async()=>{await Promise.all([store.load(),store.loadStates()]);prepareSlots();document.addEventListener('fullscreenchange',fullscreenChanged)})
onBeforeUnmount(()=>{document.removeEventListener('fullscreenchange',fullscreenChanged);for(const v of Object.values(videoRefs.value))v.pause()})
</script>
<template>
<main ref="shell" class="player-shell" :class="{immersive}">
<template v-if="page==='feed'">
<header class="topbar"><button v-if="returnPage==='creator'" class="back-feed" @click.stop="backFromPlayback">‹ 博主作品</button><button v-else class="icon" @click="toggleFullscreen">{{immersive?'×':'⛶'}}</button><div class="tabs"><button :class="{active:store.mode==='recommend'&&!store.creatorId}" @click="returnPage='feed';store.creatorId='';store.mode='recommend';store.load()">推荐</button><button :class="{active:store.mode==='creator'&&returnPage==='feed'}" @click="returnPage='feed';store.creatorId='';store.mode='creator';store.load()">博主</button><button :class="{active:store.mode==='random'}" @click="returnPage='feed';store.creatorId='';store.mode='random';store.load()">探索</button></div><select class="source-select" :value="store.source" @change="setSource(($event.target as HTMLSelectElement).value)"><option value="primary">主库</option><option value="supplement">补充</option><option value="rare">疑似绝版</option><option value="all">全部</option></select><button class="icon sound-button" @click.stop="toggleSound">{{soundOn?'🔊':'🔇'}}</button></header>
<section ref="viewport" class="viewport" @click="singleClick" @dblclick="doubleClick" @touchstart="touchStart" @touchmove="touchMove" @touchend="touchEnd" @wheel.prevent="store.next($event.deltaY>0?1:-1)"><div class="video-stage"><div v-for="i in slotIndices" :key="i" class="video-card" :class="{active:i===store.index}" :style="{transform:`translate3d(0,${(i-store.index)*100}%,0)`}"><video :ref="el=>setVideoRef(i,el)" class="video" playsinline autoplay></video></div></div><div v-if="store.loading&&!store.current" class="loading">加载中…</div><div v-if="!store.current&&!store.loading" class="loading">暂无视频</div><div v-if="videoError" class="video-error" @click.stop="singleClick">{{videoError}}<small> 点击重试</small></div><div v-if="store.current&&showMeta" class="meta"><b class="creator-link" @click.stop="openCreator({creator_id:store.current.creator_id,name:store.current.creator})">@{{store.current.creator}}</b><p>{{store.current.title||'未命名视频'}}</p><small>{{store.current.reason}}</small></div><aside v-if="store.current" class="actions"><button class="like-button" :class="{selected:store.liked.has(store.current.file_id)}" @click.stop="void store.like()">♥<small>{{store.liked.has(store.current.file_id)?'已喜欢':'喜欢'}}</small></button><button class="dislike-button" :class="{selected:store.disliked.has(store.current.file_id)}" @click.stop="void store.dislike()">⌄<small>不喜欢</small></button><button class="favorite-button" :class="{selected:store.favorited.has(store.current.file_id)}" @click.stop="void store.toggleFavorite()">☆<small>{{store.favorited.has(store.current.file_id)?'已收藏':'收藏'}}</small></button><button @click.stop="showSource">⌂<small>来源</small></button><button @click.stop="showInfo">ⓘ<small>作品信息</small></button></aside><div v-if="store.notice" class="feedback-toast">{{store.notice}}</div><div v-if="detail" class="detail-panel" @click.stop><button class="detail-close" @click="detail=''">×</button><pre>{{detail}}</pre></div></section>
</template>
<section v-else-if="page==='like'||page==='favorite'" class="collection-page"><header class="page-header"><button @click="page='feed'">‹ 返回</button><h2>{{page==='like'?'我喜欢的作品':'我的收藏'}}</h2><button @click="page='mine'">设置</button></header><div v-if="!collectionItems.length" class="empty">暂无记录</div><div class="tile-grid"><button v-for="(x,i) in collectionItems" :key="x.work_id||x.file_id" class="tile" @click="playCollection(i)"><video :src="media(x)" muted preload="metadata"></video><b>@{{x.creator}}</b><span>{{x.title||'未命名视频'}}</span></button></div></section>
<section v-else-if="page==='mine'" class="mine-page"><header class="page-header"><button @click="page='feed'">‹ 返回</button><h2>我的</h2><span></span></header><button class="settings-row" @click="openFollowing">♡ 我的关注 <span>{{followingItems.length}} 位博主　›</span></button><label>默认来源 <select :value="store.source" @change="setSource(($event.target as HTMLSelectElement).value)"><option value="primary">主库</option><option value="supplement">补充</option><option value="all">全部</option></select></label><label><input v-model="autoPlay" type="checkbox" @change="localStorage.setItem('autoplay',autoPlay?'1':'0')"> 自动播放</label><label><input v-model="showMeta" type="checkbox" @change="localStorage.setItem('showMeta',showMeta?'1':'0')"> 显示来源和作品信息</label><button class="import-button" @click="importHistory">重新导入历史 Excel</button><div v-if="historyStatus" class="history-status">已导入 {{historyStatus.matched}} 条；未匹配记录已删除 {{historyStatus.unmatched_deleted}} 条</div></section>
<section v-else-if="page==='following'" class="following-page"><header class="page-header"><button @click="page='mine'">‹ 设置</button><h2>我的关注</h2><span></span></header><form class="creator-search" @submit.prevent="searchCreators"><input v-model="followQuery" placeholder="搜索博主名称或编号"><button type="submit">搜索</button></form><h3>已关注</h3><div v-if="!followingItems.length" class="empty compact">还没有关注的博主</div><div v-for="x in followingItems" :key="x.creator_id" class="creator-row" @click="openCreator(x)"><span><b>{{x.name||'博主待确认'}}</b><small>{{x.video_count}} 个本地视频</small></span><span>查看视频　›</span></div><h3 v-if="followResults.length">搜索结果</h3><div v-for="x in followResults" :key="x.creator_id" class="creator-row"><span @click="openCreator(x)"><b>{{x.name||'博主待确认'}}</b><small>{{x.video_count}} 个本地视频</small></span><span class="row-actions"><button @click.stop="openCreator(x)">视频</button><button @click.stop="toggleFollow(x)">{{x.is_following?'已关注':'关注'}}</button></span></div><p v-if="followQuery&&!followResults.length" class="muted">点击“搜索”查找本地博主</p></section>
<section v-else class="creator-page"><header class="page-header"><button @click="page='following'">‹ 我的关注</button><h2>{{activeCreator?.name||'博主视频'}}</h2><button @click="playCreatorVideo(0)" :disabled="!creatorItems.length">播放</button></header><p class="sort-note">按历史点赞量排序 · 当前显示 {{creatorItems.length}} / {{activeCreator?.video_count||creatorItems.length}} 条</p><div v-if="!creatorItems.length&&!creatorLoading" class="empty">没有可播放的本地视频</div><div class="tile-grid"><button v-for="(x,i) in creatorItems" :key="x.work_id||x.file_id" class="tile" @click="playCreatorVideo(i)"><video :src="media(x)" muted preload="metadata"></video><b>{{i+1}}. {{x.title||'未命名视频'}}</b><span>♥ {{x.like_count==null?'无点赞记录':Number(x.like_count).toLocaleString()+' · 历史点赞量'}}</span></button></div><button v-if="creatorHasMore" class="load-more" :disabled="creatorLoading" @click="loadCreatorPage">{{creatorLoading?'加载中…':'加载更多'}}</button></section>
<nav class="bottom"><button :class="{selected:page==='feed'}" @click="page='feed'">⌂ 推荐</button><button :class="{selected:page==='like'}" @click="openCollection('like')">♡ 喜欢</button><button :class="{selected:page==='favorite'}" @click="openCollection('favorite')">☆ 收藏</button><button :class="{selected:page==='mine'}" @click="openMine">◉ 我的</button></nav></main>
</template>

